# Generated by Claude Sonnet 5.5

"""Calculate gas flux from chamber measurements.
 
F = (dC/dt) * (P_amb * V) / (R_gas * T * A)
 
Units: dC/dt in ppm h^-1 (= umol mol^-1 h^-1), P in Pa, V in m^3,
T in K, A in m^2, R = 8.314 m^3 Pa K^-1 mol^-1  ->  F in umol m^-2 h^-1
 
Edit the settings below, then run:  uv run flux.py
"""
from pathlib import Path
 
import numpy as np
import pandas as pd
 
# ----------------------------- SETTINGS -----------------------------
VOLUME = 0.019          # chamber volume (m^3)           <-- set this
AREA = 0.0714            # chamber surface area (m^2)     <-- set this
PRESSURE = 101325.0      # ambient pressure (Pa)
 
GAS_COLUMN = "co2"       # concentration column (ppm)
TEMP_COLUMN = "temp"     # temperature column (deg C)
CHAMBER_TYPE = 1         # value of 'type' when chamber is closed/measuring
 
GAP_SECONDS = 120        # time gap that splits data into separate runs
TRIM_SECONDS = 0         # seconds dropped from the start of each run
MIN_POINTS = 4           # minimum points needed to fit a run
 
DATA_DIR = Path(__file__).parent / "data"
OUT_FILE = Path(__file__).parent / "flux_results.csv"
# --------------------------------------------------------------------
 
R_GAS = 8.314  # m^3 Pa K^-1 mol^-1
 
 
def load(data_dir: Path) -> pd.DataFrame:
    frames = []
    for f in sorted(data_dir.glob("*.csv")):
        df = pd.read_csv(f, skipinitialspace=True)
        df.columns = [c.strip() for c in df.columns]
        df["file"] = f.name
        frames.append(df)
    if not frames:
        raise SystemExit(f"No .csv files found in {data_dir}")
    df = pd.concat(frames, ignore_index=True)
    df["datetime"] = pd.to_datetime(
        df["date"].str.strip() + " " + df["time"].str.strip(),
        format="%Y/%m/%d %H:%M:%S",
    )
    return df.sort_values(["file", "datetime"]).reset_index(drop=True)
 
 
def label_runs(df: pd.DataFrame) -> pd.DataFrame:
    """New run starts when the file or 'type' changes, or there is a time gap."""
    dt = df.groupby("file")["datetime"].diff().dt.total_seconds()
    new = (
        (df["file"] != df["file"].shift())
        | (df["type"] != df["type"].shift())
        | (dt > GAP_SECONDS)
    )
    df["run"] = new.cumsum()
    return df
 
 
def flux_for_run(g: pd.DataFrame) -> dict | None:
    t0 = g["datetime"].iloc[0] + pd.Timedelta(seconds=TRIM_SECONDS)
    g = g[g["datetime"] >= t0]
    if len(g) < MIN_POINTS:
        return None
    t_h = (g["datetime"] - g["datetime"].iloc[0]).dt.total_seconds().to_numpy() / 3600
    c = g[GAS_COLUMN].to_numpy(dtype=float)
    slope, intercept = np.polyfit(t_h, c, 1)  # ppm h^-1
    pred = slope * t_h + intercept
    ss_res = np.sum((c - pred) ** 2)
    ss_tot = np.sum((c - c.mean()) ** 2)
    r2 = 1 - ss_res / ss_tot if ss_tot > 0 else np.nan
 
    T_K = g[TEMP_COLUMN].mean() + 273.15
    flux = slope * (PRESSURE * VOLUME) / (R_GAS * T_K * AREA)
 
    return {
        "start": g["datetime"].iloc[0],
        "end": g["datetime"].iloc[-1],
        "n": len(g),
        "dCdt_ppm_h": slope,
        "r2": r2,
        "T_K": T_K,
        "flux_umol_m2_h": flux,
    }
 
 
def main():
    df = label_runs(load(DATA_DIR))
    df = df[df["type"] == CHAMBER_TYPE]
 
    rows = [r for _, g in df.groupby("run") if (r := flux_for_run(g))]
    if not rows:
        raise SystemExit("No runs with enough points.")
 
    res = pd.DataFrame(rows)
    res.to_csv(OUT_FILE, index=False)
    print(res.to_string(index=False, float_format=lambda x: f"{x:.4g}"))
    print(f"\nSaved to {OUT_FILE}")
 
 
if __name__ == "__main__":
    main()
